/**
 * Mock fragrance catalog used until the Supabase + scraper pipeline is live.
 *
 * Curated to span niche luxury (MFK, Creed, Tom Ford), designer luxury
 * (Chanel, Dior, YSL), and cult favorites (Le Labo, Byredo, Diptyque) so
 * the home/discover/wardrobe/train screens look like a real catalog.
 *
 * Image URLs use Unsplash — no copyrighted brand assets in the demo. When
 * the real scraper pipeline runs, image_url is replaced with the brand-direct
 * or retailer hero shot.
 *
 * NOT loaded in production builds — `useCatalog()` swaps to the Supabase
 * client when `isSupabaseConfigured` is true.
 */

export interface MockFragrance {
  id: string;
  brand: string;
  name: string;
  concentration: 'parfum' | 'edp' | 'edt' | 'cologne' | 'extrait';
  fragrance_family: string;
  gender: 'feminine' | 'masculine' | 'unisex';
  top_notes: string[];
  heart_notes: string[];
  base_notes: string[];
  top_accords: string[];
  accord_intensity: Record<string, number>;
  community_longevity: number;     // 0..5
  community_sillage: number;       // 0..5
  community_projection: number;    // 0..5
  compliment_score: number;        // 0..1
  versatility_score: number;       // 0..1
  office_safe_score: number;       // 0..1
  price_tier: number;              // 1..5
  retail_msrp_usd_cents: number;
  image_url: string;
  similar_ids: string[];
  dupe_of?: string | null;
  release_year: number;
}




